static vector<string> parseStringArray(string s) {
    vector<string> list;
    size_t first = s.find('[');
    size_t last = s.rfind(']');
    if (first != string::npos && last != string::npos && last > first) {
        s = s.substr(first + 1, last - first - 1);
    }
    bool inQuotes = false;
    string cur = "";
    for (char c : s) {
        if (c == '"') {
            inQuotes = !inQuotes;
        } else if (c == ',' && !inQuotes) {
            while (!cur.empty() && isspace(cur.front())) cur.erase(cur.begin());
            while (!cur.empty() && isspace(cur.back())) cur.pop_back();
            if (!cur.empty()) list.push_back(cur);
            cur = "";
        } else {
            cur += c;
        }
    }
    while (!cur.empty() && isspace(cur.front())) cur.erase(cur.begin());
    while (!cur.empty() && isspace(cur.back())) cur.pop_back();
    if (!cur.empty()) list.push_back(cur);
    return list;
}

static vector<string> splitTopLevel(string s) {
    vector<string> list;
    size_t first = s.find('[');
    size_t last = s.rfind(']');
    if (first != string::npos && last != string::npos && last > first) {
        s = s.substr(first + 1, last - first - 1);
    }
    int depth = 0;
    bool inQuotes = false;
    string cur = "";
    for (char c : s) {
        if (c == '"') inQuotes = !inQuotes;
        else if (!inQuotes && (c == '[' || c == '{')) depth++;
        else if (!inQuotes && (c == ']' || c == '}')) depth--;
        else if (!inQuotes && c == ',' && depth == 0) {
            while (!cur.empty() && isspace(cur.front())) cur.erase(cur.begin());
            while (!cur.empty() && isspace(cur.back())) cur.pop_back();
            list.push_back(cur);
            cur = "";
            continue;
        }
        cur += c;
    }
    while (!cur.empty() && isspace(cur.front())) cur.erase(cur.begin());
    while (!cur.empty() && isspace(cur.back())) cur.pop_back();
    if (!cur.empty()) list.push_back(cur);
    return list;
}

static vector<int> parseIntArray(string s) {
    vector<string> items = splitTopLevel(s);
    vector<int> res;
    for (const auto& item : items) {
        if (!item.empty()) res.push_back(stoi(item));
    }
    return res;
}

