        int[] arr = new int[items.size()];
        for (int i = 0; i < items.size(); i++) {
            String it = items.get(i).trim();
            if (!it.isEmpty()) arr[i] = Integer.parseInt(it);
        }
        return arr;
    }

    public static void main(String[] args) throws Exception {
