            if (c == '"') inQuotes = !inQuotes;
            else if (!inQuotes && (c == '[' || c == '{')) depth++;
            else if (!inQuotes && (c == ']' || c == '}')) depth--;
            else if (!inQuotes && c == ',' && depth == 0) {
                list.add(sb.toString().trim());
                sb.setLength(0);
                continue;
            }
            sb.append(c);
        }
        if (sb.length() > 0) list.add(sb.toString().trim());
        return list;
    }

